                                recurrence_date: date.format("%Y-%m-%d").to_string(),
                                expected_version,
                                event: EventMutation {
                                    title: exception.summary.clone(),
                                    description: exception.description.clone(),
                                    location: exception.location.clone(),
                                    status: exc_status,
                                    timing: exc_timing,
