                CaldavAuthError::ResourceExists => {
                    (StatusCode::PRECONDITION_FAILED, "resource already exists").into_response()
                }
                CaldavAuthError::UidConflict => {
                    (StatusCode::CONFLICT, "uid already exists in calendar").into_response()
                }
                _ => dav_server_error(),
            };
        }
    };

